mapper.select:
SELECT DISTINCT v.id, v.jp_company_name, v.short_company_name, v.abbreviation, v.region, v.headquarters_address, v.contact_person, v.total_sales_avg, v.breakthrough_status, v.hw_sales_avg, v.estimated_increase, v.sales_plan, v.remarks, v.installer_event_participation, v.branch_name, v.company_type, ( SELECT GROUP_CONCAT(oa2.agent_name ORDER BY FIELD(oa2.agent_name, 'XSOL', 'DMM', 'WWB', '高島', '韓華') SEPARATOR ',') FROM addressmap.tab_outlet_agent oa2 WHERE oa2.outlet_id = v.id ) AS businessflow, v.cpn_type, v.sales_record, v.lat, v.lng FROM ( SELECT o.id, o.jp_company_name, o.short_company_name, o.abbreviation, o.region, o.headquarters_address, o.contact_person, o.total_sales_avg, o.breakthrough_status, o.hw_sales_avg, o.estimated_increase, o.sales_plan, o.remarks, o.installer_event_participation, NULL AS branch_name, '販売店' AS company_type, o.cpn_type, o.sales_record, o.lat, o.lng FROM addressmap.tab_outlet o ) v INNER JOIN addressmap.tab_outlet_agent oa ON oa.outlet_id = v.id WHERE oa.agent_name IN
#{businessflow}
ORDER BY v.id
